    function updateScrollProgress() {
      const scrollPosition = window.scrollY;
      const scrollPercentage = (scrollPosition / (document.documentElement.scrollHeight - document.documentElement.clientHeight)) * 100;
      const progressWidth = (scrollPercentage / 100) * 100;
      scrollProgress.style.width = progressWidth + '%';
    }

    window.addEventListener('scroll', updateScrollProgress);

    sections.forEach((section, index) => {
      section.addEventListener('scroll', () => {
        const revealElements = section.querySelectorAll('.reveal');
        revealElements.forEach(reveal => {
          const revealTop = reveal.getBoundingClientRect().top;
          const windowHeight = window.innerHeight;
          if (revealTop < windowHeight && revealTop + reveal.offsetHeight > 0) {
            reveal.classList.add('active');
          } else {
            reveal.classList.remove('active');
          }
        });
