    background: rgba(15, 15, 35, 0.95);
    backdrop-filter: blur(10px);
    padding: 15px 0;
    position: fixed;
    width: 100%;
    top: 0;
    z-index: 100;
    border-bottom: 1px solid var(--border);
}

.nav-container {
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.logo {
    font-size: 1.8rem;
    font-weight: 700;
    color: #fff;
    text-decoration: none;
    background: var(--gradient);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
}

.nav-links {
    display: flex;
    gap: 30px;
    list-style: none;
    align-items: center;
}

.nav-links a {
    color: var(--text-muted);
    text-decoration: none;
    font-size: 0.95rem;
    transition: color 0.3s;
}

.nav-links a:hover {
    color: #fff;
}

.btn {
    display: inline-block;
    padding: 10px 20px;
    border-radius: 8px;
    text-decoration: none;
    font-weight: 500;
    transition: all 0.3s;
    cursor: pointer;
    border: none;
    font-size: 0.95rem;
}

.btn-primary {
    background: var(--primary);
    color: #fff;
}

.btn-primary:hover {
    background: var(--primary-dark);
    transform: translateY(-2px);
    box-shadow: 0 4px 15px rgba(108, 99, 255, 0.4);
}

.btn-outline {
    background: transparent;
    color: var(--text);
    border: 1px solid var(--border);
}

.btn-outline:hover {
    border-color: var(--primary);
    color: #fff;
}

.btn-lg {
    padding: 14px 30px;
    font-size: 1rem;
}

.hamburger {
    display: none;
    flex-direction: column;
    gap: 5px;
    background: none;
    border: none;
    cursor: pointer;
}

.hamburger span {
    width: 25px;
    height: 3px;
    background: #fff;
    border-radius: 3px;
}

/* Hero */
.hero {
    padding: 180px 0 100px;
    background: radial-gradient(circle at 20% 20%, rgba(108, 99, 255, 0.15), transparent 40%),
                radial-gradient(circle at 80% 80%, rgba(62, 207, 142, 0.1), transparent 40%);
}

.hero-container {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 60px;
    align-items: center;
}

.hero-title {
    font-size: 3.5rem;
    font-weight: 700;
    line-height: 1.2;
    margin-bottom: 20px;
}

.gradient-text {
    background: var(--gradient);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
}

.hero-subtitle {
    font-size: 1.2rem;
    color: var(--text-muted);
    margin-bottom: 30px;
    max-width: 500px;
}

.hero-actions {
    display: flex;
    gap: 15px;
    flex-wrap: wrap;
}

.hero-image {
    display: flex;
    justify-content: center;
}

.terminal {
    width: 100%;
    max-width: 500px;
    background: var(--dark-light);
    border-radius: 12px;
    border: 1px solid var(--border);
    box-shadow: 0 20px 40px rgba(0, 0, 0, 0.3);
    overflow: hidden;
}

.terminal-header {
    background: #2a2a4a;
    padding: 10px 15px;
    display: flex;
    align-items: center;
    gap: 8px;
}

.dot {
    width: 12px;
    height: 12px;
    border-radius: 50%;
}

.red { background: #ff5f57; }
.yellow { background: #febc2e; }
.green { background: #28c840; }

.terminal-title {
    margin-left: 10px;
    font-size: 0.85rem;
    color: var(--text-muted);
}

.terminal-body {
    padding: 20px;
    font-family: 'Courier New', monospace;
    font-size: 0.9rem;
    color: #d4d4d4;
}

.terminal-body p {
    margin-bottom: 10px;
}

.prompt {
    color: var(--primary);
    font-weight: bold;
}

.output {
    color: var(--text-muted);
    margin-left: 20px;
}

/* Sections */
.section-title {
    font-size: 2.5rem;
    font-weight: 700;
    text-align: center;
    margin-bottom: 15px;
    color: #fff;
}

.section-subtitle {
    text-align: center;
    color: var(--text-muted);
    margin-bottom: 50px;
    font-size: 1.1rem;
}

/* Features */
.features {
    padding: 100px 0;
    background: var(--dark-light);
}

.features-grid {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 30px;
}

.feature-card {
    background: var(--card-bg);
    padding: 30px;
    border-radius: 12px;
    border: 1px solid var(--border);
    transition: transform 0.3s, box-shadow 0.3s;
}

.feature-card:hover {
    transform: translateY(-5px);
    box-shadow: 0 10px 30px rgba(0, 0, 0, 0.2);
}

.feature-icon {
    font-size: 2.5rem;
    margin-bottom: 15px;
}

.feature-card h3 {
    font-size: 1.3rem;
    margin-bottom: 10px;
    color: #fff;
}

.feature-card p {
    color: var(--text-muted);
    font-size: 0.95rem;
}

/* About */
.about {
    padding: 100px 0;
}

.about-container {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 60px;
    align-items: center;
}

.about-text .section-title {
    text-align: left;
    margin-bottom: 20px;
}

.about-text p {
    color: var(--text-muted);
    margin-bottom: 20px;
}

.about-list {
    list-style: none;
    color: var(--text);
    margin-top: 20px;
}

.about-list li {
    margin-bottom: 10px;
    font-size: 1.05rem;
}

.about-stats {
    display: flex;
    flex-direction: column;
    gap: 20px;
}

.stat {
    background: var(--card-bg);
    padding: 30px;
    border-radius: 12px;
    border: 1px solid var(--border);
    text-align: center;
}

.stat-number {
    display: block;
    font-size: 2.5rem;
    font-weight: 700;
    background: var(--gradient);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
}

.stat-label {
    color: var(--text-muted);
    margin-top: 5px;
}

/* Testimonials */
.testimonials {
    padding: 100px 0;
    background: var(--dark-light);
}

.testimonial-grid {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 30px;
}

.testimonial-card {
    background: var(--card-bg);
    padding: 30px;
    border-radius: 12px;
    border: 1px solid var(--border);
}

.testimonial-card p {
    color: var(--text);
    font-style: italic;
    margin-bottom: 20px;
    font-size: 0.95rem;
}

.user {
    display: flex;
    align-items: center;
    gap: 15px;
}

.avatar {
    width: 50px;
    height: 50px;
    border-radius: 50%;
    background: var(--gradient);
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: 600;
    color: #fff;
}

.user strong {
    display: block;
    color: #fff;
}

.user span {
    font-size: 0.85rem;
    color: var(--text-muted);
}

/* CTA */
.cta {
    padding: 100px 0;
    background: var(--gradient);
    text-align: center;
}

.cta-container h2 {
    font-size: 2.5rem;
    color: #fff;
    margin-bottom: 15px;
}

.cta-container p {
    color: rgba(255, 255, 255, 0.9);
    margin-bottom: 30px;
    font-size: 1.1rem;
}

.cta .btn-primary {
    background: #fff;
    color: var(--primary);
}

.cta .btn-primary:hover {
    background: #f0f0f0;
    box-shadow: 0 4px 15px rgba(255, 255, 255, 0.4);
}

/* Footer */
.footer {
    background: var(--dark);
    padding-top: 60px;
}

.footer-container {
    display: flex;
    justify-content: space-between;
    flex-wrap: wrap;
    gap: 40px;
    padding-bottom: 40px;
}

.footer-brand p {
    color: var(--text-muted);
    margin-top: 10px;
    max-width: 250px;
}

.footer-links {
    display: flex;
    gap: 60px;
    flex-wrap: wrap;
}

.footer-links h4 {
    color: #fff;
    margin-bottom: 15px;
    font-size: 1rem;
}

.footer-links ul {
    list-style: none;
}

.footer-links li {
    margin-bottom: 8px;
}

.footer-links a {
    color: var(--text-muted);
    text-decoration: none;
    font-size: 0.9rem;
    transition: color 0.3s;
}

.footer-links a:hover {
    color: #fff;
}

.footer-bottom {
    border-top: 1px solid var(--border);
    padding: 20px 0;
    text-align: center;
    color: var(--text-muted);
    font-size: 0.85rem;
}

/* Responsive */
@media (max-width: 900px) {
    .hero-container,
    .about-container {
        grid-template-columns: 1fr;
    }

    .hero {
        padding-top: 120px;
    }

    .hero-title {
        font-size: 2.5rem;
    }

    .features-grid,
    .testimonial-grid {
        grid-template-columns: 1fr 1fr;
    }

    .nav-links {
        display: none;
        flex-direction: column;
        position: absolute;
        top: 100%;
        left: 0;
        right: 0;
        background: var(--dark-light);
        padding: 20px;
        gap: 20px;
        border-bottom: 1px solid var(--border);
    }

    .nav-links.active {
        display: flex;
    }

    .hamburger {
        display: flex;
    }
}

@media (max-width: 600px) {
    .features-grid,
    .testimonial-grid {
        grid-template-columns: 1fr;
    }

    .footer-container {
        flex-direction: column;
    }

    .footer-links {
        gap: 30px;
    }
}
