    function revealOnScroll() {
      const revealThreshold = window.innerHeight / 2;
      const revealElements = document.querySelectorAll('.reveal');

      revealElements.forEach(el => {
        const rect = el.getBoundingClientRect();
        const isRevealed = rect.top < window.innerHeight - revealThreshold;
        el.style.opacity = isRevealed ? 1 : 0;
        el.style.transform = isRevealed ? 'translateY(0)' : 'translateY(100px)';
      });
    }

    function initScrollReveal() {
      const options = {
        threshold: 0.5,
        rootMargin: '0px 0px -50px 0px'
      };
      const observer = new IntersectionObserver(revealOnScroll, options);
      observer.observe(scrollReveal);
    }

    function initTypingText() {
      const text = "Your Website Starts Here";
      const typeSpeed = 50;
      let i = 0;
      let isTyping = true;

      function type() {
        if (isTyping) {
          typingText.textContent += text[i];
          i++;
          if (i >= text.length) {
            isTyping = false;
            setTimeout(() => {
              isTyping = true;
              i = 0;
              typingText.textContent = "";
              type();
            }, 1000);
          }
        }
        setTimeout(type, typeSpeed);
      }

      type();
    }

