      const rippleDiv = document.createElement('div');
      rippleDiv.classList.add('ripple-effect');
      rippleEffect.appendChild(rippleDiv);

      rippleEffect.addEventListener('click', () => {
        rippleDiv.style.width = `${rippledEffect.offsetWidth}px`;
        rippleDiv.style.height = `${rippledEffect.offsetHeight}px`;
        rippleDiv.style.top = `${event.clientY - 10}px`;
        rippleDiv.style.left = `${event.clientX - 10}px`;
        rippleDiv.style.animation = 'ripple 1s ease-out infinite';

        setTimeout(() => {
          rippleDiv.style.animation = '';
        }, 1000);
      });
    }

